        E("comments_time_conversion", "시간 변환 주석", "def seconds_to_minutes(seconds: int) -> tuple[int, int]:", "seconds를 (온전한 분, 남은 초)로 반환하고 60으로 나누는 이유를 주석으로 작성하세요.", "단위 변환을 설명하는 주석", "seconds_to_minutes(125) == (2, 5)", "seconds_to_minutes(0) == (0, 0)", "seconds_to_minutes(60) == (1, 0)"),
        E("comments_weighted_score", "가중치 설명", "def weighted_course_score(exam: float, project: float, exam_weight: float) -> float:", "exam_weight를 시험 비중으로 사용해 최종 점수를 계산하고 가중치 합이 1이 되는 이유를 주석으로 작성하세요.", "숫자의 의미를 드러내는 주석", "weighted_course_score(80, 100, 0.75) == 85.0", "weighted_course_score(0, 100, 0) == 100.0", "weighted_course_score(100, 0, 1) == 100.0"),
        E("comments_split_bill", "정산 규칙 주석", "def split_bill(total: float, people: int) -> float:", "total을 people명이 똑같이 나눈 1인 금액을 반환하고 균등 분배 규칙을 주석으로 밝히세요. people은 양수입니다.", "숨은 정책을 코드 가까이에 기록", "split_bill(90, 3) == 30.0", "split_bill(0, 5) == 0.0", "split_bill(10, 1) == 10.0"),
