        E("naming_conventions_words_to_snake", "단어를 snake_case로", "def to_snake_case(words: list[str]) -> str:", "각 단어를 소문자로 바꾸고 밑줄로 연결하세요.", "Python 변수의 snake_case 관례", "to_snake_case(['First', 'User', 'Name']) == 'first_user_name'", "to_snake_case([]) == ''", "to_snake_case(['Already']) == 'already'"),
