        E("naming_conventions_snake_validator", "snake_case 검사", "def is_snake_case(identifier: str) -> bool:", "빈 문자열은 False입니다. 모든 문자가 소문자·숫자·밑줄이고 첫 문자는 소문자여야 True를 반환하세요.", "유효한 snake_case 식별자 조건", "is_snake_case('user_name2') is True", "is_snake_case('') is False", "is_snake_case('User_Name') is False"),
        E("naming_conventions_safe_identifier", "안전한 변수명 정리", "def sanitize_identifier(text: str) -> str:", "앞뒤 공백을 제거하고 소문자로 바꾼 뒤 공백과 하이픈을 밑줄로 바꾸세요.", "일관된 변수명 정규화", "sanitize_identifier(' User-Name ') == 'user_name'", "sanitize_identifier('') == ''", "sanitize_identifier('A B-C') == 'a_b_c'"),
        E("naming_conventions_boolean_prefix", "불리언 이름 접두사", "def boolean_variable_name(subject: str) -> str:", "subject를 소문자로 바꾸고 공백을 밑줄로 바꾼 뒤 'is_'를 앞에 붙이세요.", "불리언 의도를 나타내는 is_ 관례", "boolean_variable_name('Active User') == 'is_active_user'", "boolean_variable_name('') == 'is_'", "boolean_variable_name('READY') == 'is_ready'"),
        E("naming_conventions_module_name", "모듈 이름 만들기", "def module_name_from_title(title: str) -> str:", "title을 strip하고 공백으로 나눈 단어를 소문자 밑줄로 연결한 뒤 '.py'를 붙이세요.", "Python 모듈 파일 명명 관례", "module_name_from_title('Data Parser') == 'data_parser.py'", "module_name_from_title('') == '.py'", "module_name_from_title('  Main  App ') == 'main_app.py'"),
        E("naming_conventions_private_name", "내부용 이름 표시", "def private_variable_name(name: str) -> str:", "name의 기존 선행 밑줄을 제거하고 소문자로 바꾼 뒤 밑줄 하나를 앞에 붙이세요.", "비공개 용도를 나타내는 선행 밑줄", "private_variable_name('Cache') == '_cache'", "private_variable_name('') == '_'", "private_variable_name('__TOKEN') == '_token'"),
        E("naming_conventions_split_snake", "snake_case 읽기", "def split_snake_case(identifier: str) -> list[str]:", "밑줄로 식별자를 나누고 빈 조각은 제외한 단어 리스트를 반환하세요.", "snake_case 구성 요소 이해", "split_snake_case('first_user_name') == ['first', 'user', 'name']", "split_snake_case('') == []", "split_snake_case('_a__b_') == ['a', 'b']"),
