        E("type_errors_age_sentence", "숫자를 문장에 넣기", "def format_age_sentence(name: str, age: int) -> str:", "age 때문에 문자열 결합 오류가 나지 않도록 '<name> is <age> years old.'를 반환하세요.", "숫자를 문자열 문맥으로 변환", "format_age_sentence('Ada', 36) == 'Ada is 36 years old.'", "format_age_sentence('', 0) == ' is 0 years old.'", "format_age_sentence('A', -1) == 'A is -1 years old.'"),
        E("type_errors_sum_mixed_texts", "숫자 텍스트 목록 합계", "def sum_number_texts(values: list[str]) -> float:", "각 문자열을 float로 변환해 전체 합을 반환하세요.", "같은 수치 타입으로 통일", "sum_number_texts(['1.5', '2']) == 3.5", "sum_number_texts([]) == 0", "sum_number_texts(['-1', '1']) == 0.0"),
        E("type_errors_divide_texts", "문자열 나눗셈", "def divide_number_texts(numerator: str, denominator: str) -> float:", "두 문자열을 float로 변환해 나누세요. denominator는 0이 아닙니다.", "지원되지 않는 str 나눗셈 수정", "divide_number_texts('9', '2') == 4.5", "divide_number_texts('0', '3') == 0.0", "divide_number_texts('-6', '2') == -3.0"),
