        E("type_errors_append_single_value", "리스트에 단일 값 추가", "def append_single_value(values: list[int], value: int) -> list[int]:", "list와 int를 직접 더하지 말고 원본을 보존한 채 value 하나를 끝에 추가하세요.", "컬렉션과 원소 타입 구분", "append_single_value([1, 2], 3) == [1, 2, 3]", "append_single_value([], 0) == [0]", "append_single_value([1], 1) == [1, 1]"),
        E("type_errors_join_values", "서로 다른 값을 문자열로 결합", "def join_as_text(values: list[object], separator: str) -> str:", "모든 값을 str로 변환한 뒤 separator로 연결하세요.", "join이 요구하는 문자열 원소 타입", "join_as_text([1, True, 'x'], ',') == '1,True,x'", "join_as_text([], ',') == ''", "join_as_text([None], '-') == 'None'"),
        E("type_errors_tuple_list_concat", "tuple과 list 결합", "def combine_as_tuple(left: tuple[int, ...], right: list[int]) -> tuple[int, ...]:", "right를 tuple로 변환해 left 뒤에 이어 붙인 tuple을 반환하세요.", "서로 다른 시퀀스 타입 통일", "combine_as_tuple((1, 2), [3]) == (1, 2, 3)", "combine_as_tuple((), []) == ()", "combine_as_tuple((0,), []) == (0,)"),
