        E("empty_variable_optional_number", "선택적 숫자", "def optional_number(value: int | None) -> int:", "value가 None이면 0, 아니면 원래 정수를 반환하세요.", "숫자 0을 빈 값으로 오해하지 않기", "optional_number(None) == 0", "optional_number(0) == 0", "optional_number(-1) == -1"),
        E("empty_variable_optional_length", "선택적 문자열 길이", "def optional_text_length(text: str | None) -> int:", "text가 None이면 0, 아니면 빈 문자열을 포함해 실제 길이를 반환하세요.", "None 가드 후 안전한 연산", "optional_text_length('abc') == 3", "optional_text_length(None) == 0", "optional_text_length('') == 0"),
        E("empty_variable_first_item", "첫 값 또는 None", "def first_or_none(values: list[object]) -> object | None:", "values가 비면 None, 아니면 첫 원소를 반환하세요.", "빈 컬렉션의 sentinel 값", "first_or_none([0, 1]) == 0", "first_or_none([]) is None", "first_or_none([None]) is None"),
