        E("empty_variable_optional_items", "선택적 리스트 개수", "def optional_item_count(items: list[object] | None) -> int:", "items가 None이면 0, 아니면 리스트 길이를 반환하세요.", "선택적 컬렉션 안전 처리", "optional_item_count([1, 2]) == 2", "optional_item_count([]) == 0", "optional_item_count(None) == 0"),
