        E("empty_variable_first_present", "첫 번째 존재하는 값", "def first_present(values: list[object | None]) -> object | None:", "목록에서 처음으로 None이 아닌 값을 반환하고 모두 None이거나 비면 None을 반환하세요.", "None을 sentinel로 사용한 탐색", "first_present([None, 0, 1]) == 0", "first_present([]) is None", "first_present([None, None]) is None"),
        E("empty_variable_remove_none", "None만 제거", "def remove_none_values(values: list[object | None]) -> list[object]:", "None 원소만 제거하고 0, False, 빈 문자열은 보존하세요.", "비어 있음의 정확한 정의", "remove_none_values([None, 0, '', False]) == [0, '', False]", "remove_none_values([]) == []", "remove_none_values([None]) == []"),
